package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.SheetSections;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Shared section forms for post-creation sources and campaign copies. */
public final class DashboardEditors {
    private DashboardEditors() {}
    public static Screen identity(Screen parent,JsonObject latest,DashboardSource source){JsonObject d=SheetSections.read(latest.getAsJsonObject("sheet"),"identity");var fields=new ArrayList<RecordFormScreen.Field>();for(var spec:List.of(new String[]{"species","Species / race","128"},new String[]{"characterClass","Class","128"},new String[]{"subclass","Subclass","128"},new String[]{"background","Background","128"},new String[]{"alignment","Alignment","128"},new String[]{"age","Age","128"},new String[]{"height","Height / build","128"},new String[]{"appearance","Appearance","2048"},new String[]{"biography","Biography / notes","2048"},new String[]{"personality","Personality traits","2048"},new String[]{"ideals","Ideals","2048"},new String[]{"bonds","Bonds","2048"},new String[]{"flaws","Flaws","2048"}))fields.add(new RecordFormScreen.Field(spec[0],spec[1],text(d,spec[0]),Integer.parseInt(spec[2])));return form(parent,"Character identity and details",latest,source,"identity",fields,(state,v)->{JsonObject o=SheetSections.read(state.getAsJsonObject("sheet"),"identity");v.forEach(o::addProperty);return o;},"Uses canonical identity fields. Pronouns and weight still have no separate backend fields. Campaign edits may invalidate approval under policy.");}
    public static Screen notes(Screen parent,JsonObject latest,DashboardSource source){JsonObject d=SheetSections.read(latest.getAsJsonObject("sheet"),"identity");var fields=List.of(new RecordFormScreen.Field("biography","Biography / general notes",text(d,"biography"),2048),new RecordFormScreen.Field("appearance","Appearance notes",text(d,"appearance"),2048),new RecordFormScreen.Field("personality","Personality traits",text(d,"personality"),2048),new RecordFormScreen.Field("ideals","Ideals",text(d,"ideals"),2048),new RecordFormScreen.Field("bonds","Bonds",text(d,"bonds"),2048),new RecordFormScreen.Field("flaws","Flaws",text(d,"flaws"),2048));return form(parent,"Character notes",latest,source,"identity",fields,(state,v)->{JsonObject o=SheetSections.read(state.getAsJsonObject("sheet"),"identity");v.forEach(o::addProperty);return o;},"No separate unlimited notes field exists. These bounded documented narrative fields preserve unsaved text until acknowledged.");}
    public static Screen proficiencies(Screen parent,JsonObject latest,DashboardSource source){JsonObject d=SheetSections.read(latest.getAsJsonObject("sheet"),"proficiencies");var fields=new ArrayList<RecordFormScreen.Field>();for(String key:List.of("skills","saves","tools","languages","expertise"))fields.add(new RecordFormScreen.Field(key,Character.toUpperCase(key.charAt(0))+key.substring(1)+" (comma separated)",join(d,key),1024));return form(parent,"Recorded proficiencies",latest,source,"proficiencies",fields,(state,v)->{JsonObject o=SheetSections.read(state.getAsJsonObject("sheet"),"proficiencies");o.add("skills",WizardEditors.array(v.get("skills"),32));o.add("saves",WizardEditors.array(v.get("saves"),6));o.add("tools",WizardEditors.array(v.get("tools"),32));o.add("languages",WizardEditors.array(v.get("languages"),32));o.add("expertise",WizardEditors.array(v.get("expertise"),32));return o;},"Recorded proficiencies remain manual/informational and do not alter authoritative attack or save calculations.");}
    public static Screen tools(Screen parent,JsonObject latest,DashboardSource source){var current=SheetSections.read(latest.getAsJsonObject("sheet"),"proficiencies");String custom=DashboardModel.strings(current,"skills").stream().filter(name->DashboardModel.SKILLS.keySet().stream().noneMatch(k->k.equalsIgnoreCase(name))).reduce((a,b)->a+", "+b).orElse("");var fields=List.of(new RecordFormScreen.Field("tools","Tools",join(current,"tools"),512),new RecordFormScreen.Field("languages","Languages",join(current,"languages"),512),new RecordFormScreen.Field("customSkills","Other skill entries (custom)",custom,512));return form(parent,"Tools, languages and personal entries",latest,source,"proficiencies",fields,(state,values)->{var p=SheetSections.read(state.getAsJsonObject("sheet"),"proficiencies");p.add("tools",WizardEditors.array(values.get("tools"),32));p.add("languages",WizardEditors.array(values.get("languages"),32));var skills=new JsonArray();for(var name:array(p,"skills"))if(DashboardModel.SKILLS.keySet().stream().anyMatch(k->k.equalsIgnoreCase(name.getAsString())))skills.add(name);for(var name:WizardEditors.array(values.get("customSkills"),32))skills.add(name);p.add("skills",skills);return ProficiencyModel.normalized(p);},"Personal entries require your DM's ruling and do not change automated combat.");}
    public static Screen progression(Screen parent,JsonObject latest,DashboardSource source){JsonObject d=SheetSections.read(latest.getAsJsonObject("sheet"),"progression");var fields=List.of(new RecordFormScreen.Field("recordedLevel","Recorded level (1–20)",text(d,"recordedLevel"),2),new RecordFormScreen.Field("xp","Recorded XP",text(d,"xp"),10),new RecordFormScreen.Field("mode","XP, MILESTONE or DM_MANAGED",text(d,"mode"),16));return form(parent,"Recorded progression",latest,source,"progression",fields,(state,v)->{JsonObject o=SheetSections.read(state.getAsJsonObject("sheet"),"progression");o.addProperty("recordedLevel",WizardEditors.integer(v,"recordedLevel",1,20));o.addProperty("xp",WizardEditors.longNumber(v,"xp",0,1_000_000_000L));String mode=v.get("mode").trim().toUpperCase(Locale.ROOT);if(!Set.of("XP","MILESTONE","DM_MANAGED").contains(mode))throw new IllegalArgumentException("Mode must be XP, MILESTONE or DM_MANAGED");o.addProperty("mode",mode);return o;},"Progression is informational. Saving does not level authoritative combat statistics; campaign edits may invalidate approval.");}
    private static RecordFormScreen form(Screen parent,String title,JsonObject latest,DashboardSource source,String section,List<RecordFormScreen.Field> fields,java.util.function.BiFunction<JsonObject,Map<String,String>,JsonObject> data,String note){return new RecordFormScreen(parent,title,source.read(),source.readArgs(),fields,(state,v)->source.sectionArgs(state,section,data.apply(state,v)),source.edit(),saved->MinecraftClient.getInstance().setScreen(parent),note).expected(latest);}
    private static String join(JsonObject o,String key){var values=new ArrayList<String>();for(var e:array(o,key))values.add(e.getAsString());return String.join(", ",values);}
}
